export const blurIcon = "blur(2px)";

export function flipTransform(side: "top" | "bottom" | "left" | "right") {
  const rotate =
    side === "top"
      ? "rotateX(-20deg)"
      : side === "bottom"
        ? "rotateX(20deg)"
        : side === "left"
          ? "rotateY(20deg)"
          : "rotateY(-20deg)";
  return `perspective(500px) ${rotate} scale(0.8)`;
}

export function uprightTransform(side: "top" | "bottom" | "left" | "right") {
  const rotate = side === "left" || side === "right" ? "rotateY(0deg)" : "rotateX(0deg)";
  return `perspective(500px) ${rotate} scale(1)`;
}

"use client";

import * as React from "react";
import { useInView } from "motion/react";
import { usePageVisible, useReduceMotion } from "../motion";

export function useBackgroundPlayback(ref: React.RefObject<Element | null>) {
  const inView = useInView(ref);
  const pageVisible = usePageVisible();
  const reduce = useReduceMotion();
  return {
    inView,
    pageVisible,
    reduce,
    playing: inView && pageVisible && !reduce,
  };
}

export function seeded(index: number, salt = 1) {
  const value = Math.sin(index * 127.1 * salt + 311.7) * 43758.5453;
  return value - Math.floor(value);
}

export function useIsDark(ref: React.RefObject<Element | null>) {
  const [dark, setDark] = React.useState(false);

  React.useEffect(() => {
    const element = ref.current;
    if (!element) return;
    const read = () =>
      setDark(
        element.classList.contains("dark") ||
          document.documentElement.classList.contains("dark"),
      );
    read();
    const observer = new MutationObserver(read);
    observer.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class", "data-theme", "style"],
    });
    return () => observer.disconnect();
  }, [ref]);

  return dark;
}

export function useCanvasSize(
  containerRef: React.RefObject<HTMLDivElement | null>,
  canvasRef: React.RefObject<HTMLCanvasElement | null>,
  onChange: () => void,
) {
  const changeRef = React.useRef(onChange);
  changeRef.current = onChange;

  React.useEffect(() => {
    const container = containerRef.current;
    const canvas = canvasRef.current;
    if (!container || !canvas) return;

    const resize = () => {
      const rect = container.getBoundingClientRect();
      const dpr = Math.max(1, Math.min(window.devicePixelRatio || 1, 2));
      const width = Math.max(1, Math.round(rect.width * dpr));
      const height = Math.max(1, Math.round(rect.height * dpr));
      if (canvas.width !== width || canvas.height !== height) {
        canvas.width = width;
        canvas.height = height;
      }
      canvas.style.width = `${rect.width}px`;
      canvas.style.height = `${rect.height}px`;
      changeRef.current();
    };

    resize();
    const observer = new ResizeObserver(resize);
    observer.observe(container);
    window.addEventListener("resize", resize);
    return () => {
      observer.disconnect();
      window.removeEventListener("resize", resize);
    };
  }, [canvasRef, containerRef]);
}

"use client";

import * as React from "react";
import { motion } from "motion/react";
import { cn } from "@/lib/utils";
import { useBackgroundPlayback } from "./shared";

export type GradientBackgroundProps = React.ComponentProps<"div"> & {
  speed?: number;
  paused?: boolean;
  gradient?: string;
};

const DEFAULT_GRADIENT =
  "linear-gradient(120deg, #312e81 0%, #6d28d9 24%, #be185d 48%, #c2410c 72%, #0f766e 100%)";

export function GradientBackground({
  speed = 1,
  paused = false,
  gradient = DEFAULT_GRADIENT,
  className,
  children,
  ...props
}: GradientBackgroundProps) {
  const ref = React.useRef<HTMLDivElement>(null);
  const { playing: live, reduce } = useBackgroundPlayback(ref);
  const playing = live && !paused;
  const duration = 16 / Math.max(0.1, speed);

  return (
    <div
      ref={ref}
      data-slot="gradient-background"
      className={cn("relative size-full overflow-hidden bg-[#0a0910]", className)}
      {...props}
    >
      <motion.div
        aria-hidden="true"
        animate={
          playing
            ? { backgroundPosition: ["0% 50%", "100% 50%", "0% 50%"] }
            : { backgroundPosition: "0% 50%" }
        }
        transition={
          playing
            ? { duration, ease: "easeInOut", repeat: Infinity }
            : { duration: 0 }
        }
        className="absolute -inset-[35%] opacity-90 blur-[10px]"
        style={{
          backgroundImage: gradient,
          backgroundSize: "400% 400%",
          backgroundPosition: reduce ? "35% 50%" : undefined,
          willChange: "background-position",
        }}
      />
      <motion.div
        aria-hidden="true"
        animate={
          playing
            ? { x: ["-12%", "14%", "-12%"], y: ["-8%", "10%", "-8%"], scale: [1, 1.25, 1] }
            : { x: "-12%", y: "-8%" }
        }
        transition={
          playing
            ? { duration: duration * 1.6, ease: "easeInOut", repeat: Infinity }
            : { duration: 0 }
        }
        className="absolute left-[8%] top-[4%] size-[70%] rounded-full opacity-70 blur-[60px]"
        style={{
          background: "radial-gradient(circle, rgba(45,212,191,0.75), transparent 68%)",
          willChange: "transform",
        }}
      />
      <motion.div
        aria-hidden="true"
        animate={
          playing
            ? { x: ["10%", "-16%", "10%"], y: ["12%", "-10%", "12%"], scale: [1.1, 0.9, 1.1] }
            : { x: "10%", y: "12%" }
        }
        transition={
          playing
            ? { duration: duration * 2.1, ease: "easeInOut", repeat: Infinity }
            : { duration: 0 }
        }
        className="absolute bottom-[2%] right-[2%] size-[74%] rounded-full opacity-70 blur-[70px]"
        style={{
          background: "radial-gradient(circle, rgba(249,115,22,0.72), transparent 66%)",
          willChange: "transform",
        }}
      />
      <div
        aria-hidden="true"
        className="pointer-events-none absolute inset-0 bg-[radial-gradient(ellipse_at_center,transparent_10%,rgba(5,4,10,0.6))]"
      />
      {children}
    </div>
  );
}

"use client";

import { useReducedMotion } from "motion/react";
import { useSyncExternalStore } from "react";

const subscribe = () => () => {};

export function useHydratedReducedMotion() {
  const reduce = useReducedMotion() ?? false;
  const mounted = useSyncExternalStore(
    subscribe,
    () => true,
    () => false,
  );
  return mounted ? reduce : false;
}
